-- =========================================
-- TABLE: products
-- =========================================
CREATE TABLE IF NOT EXISTS products (
  sku_code VARCHAR PRIMARY KEY,
  sku_description VARCHAR,
  category VARCHAR,
  sub_category VARCHAR,
  grams NUMERIC,
  units_per_carton INTEGER,
  retail_price_incl NUMERIC,
  tp_incl NUMERIC,
  tp_excl NUMERIC,
  retail_price_excl NUMERIC
);
TRUNCATE TABLE products CASCADE;

-- =========================================
-- TABLE: distributors
-- =========================================
CREATE TABLE IF NOT EXISTS distributors (
  distributor_code VARCHAR PRIMARY KEY,
  distribution_name VARCHAR,
  town VARCHAR,
  zone VARCHAR,
  tier VARCHAR
);
TRUNCATE TABLE distributors CASCADE;

-- =========================================
-- TABLE: channels
-- =========================================
CREATE TABLE IF NOT EXISTS channels (
  id SERIAL PRIMARY KEY,
  system_channel VARCHAR,
  corrected_channel VARCHAR,
  short_channel_name_for_display VARCHAR,
  sub_channel VARCHAR,
  full_name VARCHAR
);
TRUNCATE TABLE channels CASCADE;

-- =========================================
-- TABLE: discount_slabs
-- =========================================
CREATE TABLE IF NOT EXISTS discount_slabs (
  id SERIAL PRIMARY KEY,
  tier VARCHAR,
  category VARCHAR,
  channel VARCHAR,
  slab VARCHAR,
  min_gross_amount NUMERIC,
  max_gross_amount NUMERIC,
  discount_pct NUMERIC
);
TRUNCATE TABLE discount_slabs CASCADE;

-- =========================================
-- TABLE: trade_offer_discount
-- =========================================
CREATE TABLE IF NOT EXISTS trade_offer_discount (
  sku_code VARCHAR PRIMARY KEY,
  product_description VARCHAR,
  gm NUMERIC,
  units_per_case INTEGER,
  gt NUMERIC,
  lmt NUMERIC,
  ws NUMERIC
);
TRUNCATE TABLE trade_offer_discount CASCADE;

-- =========================================
-- TABLE: app_users
-- =========================================
CREATE TABLE IF NOT EXISTS app_users (
  order_booker_code VARCHAR PRIMARY KEY,
  order_booker_name VARCHAR,
  distributor_code VARCHAR,
  distributor_name VARCHAR,
  town_name VARCHAR,
  tse_supervisor VARCHAR,
  zone VARCHAR,
  asm VARCHAR,
  region VARCHAR,
  rsm VARCHAR
);
TRUNCATE TABLE app_users CASCADE;

-- =========================================
-- TABLE: pjp_list
-- =========================================
CREATE TABLE IF NOT EXISTS pjp_list (
  id SERIAL PRIMARY KEY,
  pjp_code VARCHAR,
  pjp_name VARCHAR,
  order_booker_code VARCHAR,
  order_booker_name VARCHAR,
  day VARCHAR,
  distributor_code VARCHAR,
  distributor_name VARCHAR
);
TRUNCATE TABLE pjp_list CASCADE;

-- =========================================
-- TABLE: outlets & outlet_visit_schedule
-- =========================================
CREATE TABLE IF NOT EXISTS outlets (
  store_code VARCHAR PRIMARY KEY,
  store_name VARCHAR,
  latitude NUMERIC,
  longitude NUMERIC,
  channel VARCHAR,
  sub_channel VARCHAR
);
CREATE TABLE IF NOT EXISTS outlet_visit_schedule (
  id SERIAL PRIMARY KEY,
  store_code VARCHAR,
  pjp_code VARCHAR,
  pjp_name VARCHAR,
  day VARCHAR,
  order_booker_code VARCHAR,
  order_booker_name VARCHAR
);
TRUNCATE TABLE outlets CASCADE;
TRUNCATE TABLE outlet_visit_schedule CASCADE;

